import{showSpecial}from './special-infection-visuals.js?v=20261023-physicscomplete01';import{specialTasks,validSpecialAnswer,productionSteps,productionAdvance,productionLabels,assayResult}from './special-infection-models.js?v=20261023-physicscomplete01';export{showSpecial};
export function mountSpecial(l,p,root,{save,done,feedback}){let w=p.widget,tasks=specialTasks[l.widget.slice(12)];w.specialTask??=0;w.specialDrafts??={};w.specialPassed??=[];let index=w.specialTask%tasks.length,t=tasks[index],v=w.specialDrafts[index]??={state:0,answer:'',seen:[]},$=s=>root.querySelector(s);const field=(id,label,opts,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${opts.map(([a,b])=>`<option value="${a}" ${String(value)===String(a)?'selected':''}>${b}</option>`).join('')}</select>`;let body='',draw=()=>{},record=()=>true,valid=()=>false,help='';
if(t.type==='production'){v.step??=0;body='<p>Construct the sequence from source cells to purified antibody. The model separates stages for inspection.</p>'+field('productionAction','Next production action',[['stimulate','Stimulate mouse lymphocytes'],['fuse','Fuse lymphocyte with tumour partner'],['select','Select one suitable hybridoma'],['clone','Clone the selected hybridoma'],['purify','Collect and purify antibodies']],v.productionAction)+'<button class="secondary" id="advanceProduction">Apply next action →</button><p id="specialReadout" aria-live="polite"></p>'+field('cloneReason','Why start the clone from one selected cell?',[['same','Identical cells make the same antibody'],['all','Produce every possible specificity']],v.cloneReason);draw=()=>{showSpecial('fusion',{step:v.step,title:t.title,stateLabel:productionLabels[v.step]});$('#specialReadout').textContent='Stage'+v.step+'/5 · '+productionLabels[v.step];};valid=()=>v.step===5&&v.cloneReason==='same';help='Stimulate → fuse → select one suitable hybridoma → clone → collect/purify. One clone preserves the selected antibody specificity.';}
else if(t.type==='assay'){v.condition??='present';v.step??=0;body='<p>Supplied antigen-A assay: T is the target line; C is the required control. Read only at stage3. This is a mechanism analogy, not a real diagnostic test.</p>'+field('assayCondition','Compare sample/test condition',[['present','Target A present; valid flow'],['absent','Target A absent; valid flow'],['invalid','Target A present; control failure']],v.condition)+field('assayPrediction','Predict the result under these rules',[['positive','Positive: target and control lines'],['negative','Negative: control only'],['invalid','Invalid: required control absent']],v.assayPrediction)+'<button class="secondary" id="advanceAssay">Advance assay stage →</button><p id="specialReadout" aria-live="polite"></p>';draw=()=>{showSpecial('assay',{condition:v.condition,step:v.step,title:t.title,stateLabel:'Stage'+v.step+'/3 · sample left · T then C'});$('#specialReadout').textContent=['Sample and labelled antibody ready.','Matching target binds labelled antibody if present.','Target-containing complexes captured at T; control region still pending.','Result: '+assayResult(v.condition,3)+'. Interpret the required control before T.'][v.step];};record=()=>{if(v.step!==3||v.assayPrediction!==assayResult(v.condition,3)){feedback('Predict, then reach stage3. Target present gives T+C; absent gives C only; missing C makes the supplied test invalid even if T is visible.',true);return false;}if(!v.seen.includes(v.condition))v.seen.push(v.condition);return true;};valid=()=>['present','absent','invalid'].every(c=>v.seen.includes(c));help='Compare present, absent and control-failure cases. A specific assay only answers its stated target question.';}
else{body=field('specialState','Compare model state',t.states.map((s,i)=>[i,s[1]]),v.state)+field('specialPrediction',t.prompt,t.choices.map((s,i)=>[i,s]),v.answer)+'<button class="secondary" id="revealSpecial">Reveal comparison →</button><p id="specialReadout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.state;showSpecial(t.scene,{kind:t.scene,state:t.states[v.state][0],revealed:r,title:t.title,stateLabel:t.states[v.state][1],result:r?t.results[v.state]:''});$('#specialReadout').textContent=r?t.results[v.state]:'Predict before revealing.';};record=()=>{if(v.revealed!==v.state||!validSpecialAnswer(t,v.state,v.answer)){feedback(t.why+' Predict and reveal this case before recording.',true);return false;}if(!v.seen.includes(v.state))v.seen.push(v.state);return true;};valid=()=>v.seen.length===t.states.length;help=t.why;}
root.innerHTML=`<p><b>${index+1} / ${tasks.length} · ${t.title}</b></p>${body}<p id="specialEvidence"></p><div class="model-actions"><button class="secondary" id="recordSpecial">Record reasoning</button><button class="secondary" id="nextSpecial">Next challenge →</button></div><p id="specialProgress">${w.specialPassed.length} / ${tasks.length} complete</p>`;const remount=()=>mountSpecial(l,p,root,{save,done,feedback}),evidence=()=>{$('#specialEvidence').textContent=t.type==='production'?'Completed actions: '+v.step+' / '+productionSteps.length:t.type==='assay'?'Recorded: '+(v.seen.join(', ')||'none'):'Recorded: '+t.states.map((s,i)=>(v.seen.includes(i)?'✓ ':'○ ')+s[1]).join(' · ');};
for(let el of root.querySelectorAll('select'))el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='specialState'){v.state=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='specialPrediction')v.answer=val;else if(id==='assayCondition'){v.condition=val||'present';v.step=0;v.assayPrediction='';save();remount();return;}else v[id]=val;save();};
if($('#revealSpecial'))$('#revealSpecial').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.state;save();draw();feedback(validSpecialAnswer(t,v.state,v.answer)?'Prediction agrees. Record the evidence.':help,!validSpecialAnswer(t,v.state,v.answer));};
if($('#advanceProduction'))$('#advanceProduction').onclick=()=>{let next=productionAdvance(v.step,v.productionAction);if(next===v.step){feedback(v.step===5?'The production sequence is complete; explain why one clone was selected.':help,true);return;}v.step=next;v.productionAction='';save();feedback('Production stage recorded.');remount();};
if($('#advanceAssay'))$('#advanceAssay').onclick=()=>{if(!v.assayPrediction){feedback('Predict the final result first.',true);return;}v.step=Math.min(3,v.step+1);save();draw();};
$('#recordSpecial').onclick=()=>{if(record()===false)return;save();evidence();if(!valid()){feedback(help+' Complete the remaining stages/comparisons.',true);return;}if(!w.specialPassed.includes(index))w.specialPassed.push(index);if(w.specialPassed.length===tasks.length){p.widgetDone=true;done();}save();$('#specialProgress').textContent=w.specialPassed.length+' / '+tasks.length+' complete';feedback('Evidence and reasoning recorded. '+help);};$('#nextSpecial').onclick=()=>{if(!w.specialPassed.includes(index)){feedback('Complete this challenge first.',true);return;}w.specialTask=(index+1)%tasks.length;save();feedback('');remount();};draw();evidence();}
